args.command:
pnpm add -D @napi-rs/canvas playwright-core && node -e '
import fs from "fs";
const css = fs.readFileSync("fonts/fonts.css", "utf8");
const regex = /font-family:\s*\x27([^\x27]+)\x27;[\s\S]*?font-weight:\s*(\d+);[\s\S]*?src:\s*url\(([^)]+)\)/g;
let m;
for (const match of css.matchAll(regex)) {
  const family = match[1].replace(/\s+/g, "");
  const weight = match[2];
  const url = match[3];
  console.log(`${family}-${weight}.ttf ${url}`);
}
' | while read name url; do curl -sL "$url" -o "fonts/$name"; done && ls -lh fonts/*.ttf

